const stripAnsi = require(`strip-ansi`)

const isResource = type => type && (type === `Input` || providedResources[type])

// Normalize a plan item so it always exposes a resource type name and a
// diff that is safe for non-terminal contexts (e.g. web UIs).
const normalizePlan = (plan, type) => {
  const resourceName = plan.resourceName || plan._type || type
  const normalized = {
    ...plan,
    resourceName,
    _type: plan._type || resourceName,
  }

  if (typeof normalized.diff === `string`) {
    normalized.diff = stripAnsi(normalized.diff)
  }

  return normalized
}

