+    root
+  }, id)) || {}; // eslint-disable-next-line
+
+  const fullFilePathToShadow = path.join(root, `node_modules`, theme, filePath);
+  const newContents = await fs.readFile(fullFilePathToShadow, `utf8`);
+  const newResource = {
+    id,
+    theme,
+    path: filePath,
+    contents: newContents
