+afa94d0282d048e1347cd6d47687acd5
+"use strict";
+
+const render = require(`.`);
+
+const {
+  parse
+} = require(`../parser`);
+
+const mdxFixture = `
+# Hello, world!
+
+---
+
+export const fooContent = 'hiiiiii!'
+
+<File path="foo.js" content={fooContent} />
+<File path="foo2.js" content="/** foo2 */" />
+<NPMPackage name="gatsby" />
+`;
+describe(`renderer`, () => {
+  test(`handles MDX as input`, async () => {
+    const {
+      stepsAsMdx,
+      exportsAsMdx
+    } = await parse(mdxFixture);
+    const result = await render([...stepsAsMdx, ...exportsAsMdx].join(`\n`)); // Gatsby latest version is ever changing so we use regex matcher for currentState property.
+    // Unfortunately jest property matchers work weirdly on arrays so instead
+    // of snapshotting entitre result array it's split into few pieces.
+
+    expect(result.length).toEqual(3);
+    delete result[0]._uuid;
+    delete result[1]._uuid;
+    delete result[2]._uuid;
+    expect(result[0]).toMatchInlineSnapshot(`
+      Object {
+        "_stepMetadata": Object {
+          "step": "1",
+          "totalSteps": "1",
+        },
+        "currentState": "",
+        "describe": "Write foo.js",
+        "diff": "[31m- Original  - 0[39m
+      [32m+ Modified  + 1[39m
+
+      [32m+ hiiiiii![39m",
+        "newState": "hiiiiii!",
+        "resourceDefinitions": Object {
+          "content": "hiiiiii!",
+          "mdxType": "File",
+          "path": "foo.js",
+        },
+        "resourceName": "File",
+      }
+    `);
+    expect(result[1]).toMatchInlineSnapshot(`
+      Object {
+        "_stepMetadata": Object {
+          "step": "1",
+          "totalSteps": "1",
+        },
+        "currentState": "",
+        "describe": "Write foo2.js",
+        "diff": "[31m- Original  - 0[39m
+      [32m+ Modified  + 1[39m
+
+      [32m+ /** foo2 */[39m",
+        "newState": "/** foo2 */",
+        "resourceDefinitions": Object {
+          "content": "/** foo2 */",
+          "mdxType": "File",
+          "path": "foo2.js",
+        },
+        "resourceName": "File",
+      }
+    `);
+    expect(result[2]).toMatchInlineSnapshot(`
+      Object {
+        "_stepMetadata": Object {
+          "step": "1",
+          "totalSteps": "1",
+        },
+        "currentState": "gatsby@2.24.7",
+        "describe": "Install gatsby@latest",
+        "newState": "gatsby@latest",
+        "resourceDefinitions": Object {
+          "mdxType": "NPMPackage",
+          "name": "gatsby",
+        },
+        "resourceName": "NPMPackage",
+      }
+    `);
+  });
+  test(`handles JSX with a single component`, async () => {
+    const result = await render(`<File path="hi.md" content="hi" />`);
+    expect(result).toMatchInlineSnapshot(`
+      Array [
+        Object {
+          "_stepMetadata": Object {},
+          "currentState": "",
