+const reconciler = ReactReconciler({
+  finalizeInitialChildren(element, type, props) {},
+
+  getChildHostContext(parentContext, fiberType, rootInstance) {},
+
+  getRootHostContext(rootInstance) {
+    return {
+      type: `recipes-root`
+    };
+  },
+
+  shouldSetTextContent(type, props) {},
+
+  resetTextContent(element) {},
+
+  createInstance(type, props, rootContainerInstance, hostContext, internalInstanceHandle) {
+    const instance = {
+      type,
+      props
+    };
+    debug(`creating instance`, instance);
+    return instance;
+  },
+
+  createTextInstance(text, rootContainerInstance, hostContext, internalInstanceHandle) {
+    debug(`creating text instance`, text);
+    return {
+      text
+    };
+  },
+
+  commitTextUpdate(textInstance, oldText, newText) {
+    debug(`updating text instance`, text);
+    textInstance.text = newText;
+    return textInstance;
+  },
+
+  appendChildToContainer(container, child) {
+    container.children = container.children || [];
+    const propName = child.key ? `key` : `_uuid`;
+    const index = container.children.findIndex(c => c[propName] === child[propName]);
+    debug(`appending child to container at index ${index}`);
+
+    if (index === -1) {
+      container.children.push(child);
+    } else {
+      container.children[index] = child;
+    }
+
+    return container;
+  },
+
+  appendChild(parent, child) {
+    debug(`appending child`, {
+      parent,
+      child
+    });
+    parent.children = parent.children || [];
+    parent.children.push(child);
+  },
+
+  appendInitialChild(parent, child) {
+    debug(`appending initial child`, {
+      parent,
+      child
+    });
+    parent.children = parent.children || [];
+    parent.children.push(child);
+  },
+
+  removeChildFromContainer(container, child) {},
+
+  removeChild(parent, child) {},
+
